List<Account> accounts = new List<Account>{new Account(Name = 'Locator One'), new Account(Name = 'Locator Two')};
insert accounts;
Set<Id> accountIds = new Set<Id>{accounts[0].Id, accounts[1].Id};
String queryText = 'SELECT Id, Name FROM Account WHERE Id IN :accountIds ORDER BY Name';
Database.QueryLocator locator = Database.getQueryLocator(queryText);
System.assertEquals(queryText, locator.getQuery());
Database.QueryLocatorIterator rowIterator = locator.iterator();
System.assert(rowIterator.hasNext());
System.assertEquals('Locator One', ((Account)rowIterator.next()).Name);
System.assert(rowIterator.hasNext());
System.assertEquals('Locator Two', ((Account)rowIterator.next()).Name);
System.assertEquals(false, rowIterator.hasNext());
